export function getTrackYoutubeVideoId(albumId: string, trackNum: number): string | null {
  const albumMap = ALBUMS_YOUTUBE_CATALOG[albumId];
  if (!albumMap) return null;
  return albumMap[trackNum] ?? albumMap[1] ?? null;
}
